// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 interfaceId, address target, uint256 value, bytes memory data, bytes32 predecessor, bytes32 salt, uint256 delay) public {
        // Schedule and then cancel an operation
        vm.assume(delay >= 0 && delay <= 1000000);

        // Setup roles: give PROPOSER_ROLE to address(this)
        bytes32 PROPOSER_ROLE = c.PROPOSER_ROLE();

        // Grant PROPOSER_ROLE to this contract
        vm.prank(address(c));
        c.grantRole(PROPOSER_ROLE, address(this));

        // Schedule the operation
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 operationId = c.hashOperation(target, value, data, predecessor, salt);

        // Now cancel it - this should make the operation no longer pending
        c.cancel(operationId);

        // After cancel, operation timestamp should be 0 (cancelled)
        uint256 timestamp = c.getTimestamp(operationId);

        // The general rule: after a successful cancel, supportsInterface correctly identifies IAccessControl interface
        bytes32 IACCESS_CONTROL_INTERFACE_ID = 0x7965db0b;
        bool supportsIAccessControl = c.supportsInterface(0x7965db0b);

        // After cancel, the operation should NOT be pending and supportsInterface should work correctly
        assertTrue(timestamp == 0 && supportsIAccessControl == (interfaceId == 0x7965db0b || interfaceId == 0x01ffc9a7));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id) public {
        // Ensure the operation id is scheduled first so cancel can be called
        // We need a proposer role to schedule, but address(this) already has it from setUp
        bytes32 salt = keccak256(abi.encode(id));
        bytes32 opId = c.hashOperation(address(this), 0, "", bytes32(0), salt);

        // Schedule the operation with sufficient delay
        if (!c.isOperation(opId)) {
            c.schedule(address(this), 0, "", bytes32(0), salt, 1);
        }

        // Now cancel
        if (c.isOperationPending(opId)) {
            c.cancel(opId);
        }

        // The invariant: supportsInterface must still return true for IAccessControl
        assertTrue(c.supportsInterface(0x7965db0b));
    }
}

