// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address cancelAddr) public {
        // The reference C grants DEFAULT_ADMIN_ROLE to msg.sender (address(this)) and address(this) again.
        // So after setUp, address(this) must have DEFAULT_ADMIN_ROLE.
        // The mutant's hasRole returns false always, so it will break this rule.
        // We also test that cancel reverts only when the operation is not pending, which depends on hasRole.
        bytes32 id = keccak256("test");
        vm.assume(cancelAddr != address(0));
        vm.assume(cancelAddr != address(this));
        // Try to cancel a non-existent operation from an address without PROPOSER_ROLE (to avoid revert due to role check)
        vm.prank(cancelAddr);
        (bool success, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", id));
        // The reference C reverts because caller doesn't have PROPOSER_ROLE (checked in hasRole)
        // The mutant C reverts because hasRole returns false -> role check fails
        // Both revert, but the rule we test is: hasRole for address(this) should return true
        assertTrue(c.hasRole(c.DEFAULT_ADMIN_ROLE(), address(this)));
    }
}

