        // We'll use a simple target (this contract) with no data and value 0
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = id;
        uint256 delay = 0; // minimal delay
        c.schedule(address(this), value, data, predecessor, salt, delay);
        // Warp forward so it's ready
        vm.warp(block.timestamp + 1);
        c.execute(address(this), value, data, predecessor, salt);
        // Now the timestamp for this id should be 1 (DONE_TIMESTAMP)
        // Check the rule: isOperation(id) should return true if timestamp > 0
        // In reference: timestamp=1 > 0 => true
        // In buggy: timestamp=1 > 1 => false
        bool refResult = c.isOperation(id);
        // The rule we want to assert: the reference returns true for timestamp=1
        // But we don't know which version we are testing.
        // However, the test must pass on reference and fail on buggy.
        // So we assert that isOperation returns true (which is true for reference, false for buggy)
        assertTrue(refResult);
    }
}

