    function testFuzz_property(bytes32 id) public {
        // Attempt to schedule an operation so we have something to cancel
        // We'll try to schedule with a delay of 0 (which is allowed since minDelay is 0)
        // But we need a valid target, value, data, etc.
        // Use address(0) and empty data to avoid side effects
        address target = address(0);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
