        // Use try/catch to handle reversion
        try c.schedule(target, value, data, predecessor, salt, delay) {
            // scheduled successfully
        } catch {
            // If scheduling fails, we cannot test cancel on this id, so we assume it's already scheduled or invalid
            // We'll just skip this iteration
            return;
        }

        // Now check isOperationPending before cancel
        bool wasPending = c.isOperationPending(id);

        // Attempt to cancel
        // cancel may revert if operation is not pending or caller doesn't have proposer role
        // Since we are proposer, it should succeed if pending
        try c.cancel(id) {
